.bookmark-description { margin: 0 0 9px; color: var(--muted); font-size: 13px; line-height: 1.5; }
.compact .bookmark-title, .compact .bookmark-description, .compact .note-text { display: -webkit-box; -webkit-box-orient: vertical; overflow: hidden; }
.compact .bookmark-title { -webkit-line-clamp: 2; }
.compact .bookmark-description, .compact .note-text { -webkit-line-clamp: 2; }
.compact.is-expanded .bookmark-title, .compact.is-expanded .bookmark-description, .compact.is-expanded .note-text { -webkit-line-clamp: unset; }
.bookmark-meta { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.domain { color: #7b8581; font-size: 11px; }
.tag-chip { display: inline-flex; align-items: center; border: 0; border-radius: 999px; padding: 5px 9px; color: var(--tag-ink); background: var(--tag); font-size: 11px; font-weight: 760; }
.note-block { margin-top: 12px; padding: 10px 11px; border-radius: 9px; color: #41564c; background: #eaf0eb; font-size: 12px; line-height: 1.5; }
.note-block strong { display: block; margin-bottom: 2px; }
.note-match { background: #e5edf1; color: #405965; }
.card-actions { display: flex; gap: 7px; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
.card-button { min-height: 35px; border: 1px solid #ccd1ca; border-radius: 8px; padding: 7px 10px; color: var(--navy); background: #fff; font-size: 12px; font-weight: 750; }
.card-button:hover { background: var(--mint); }
.card-button.is-on { color: #fff; border-color: var(--navy); background: var(--navy); }
.show-more { display: inline-block; margin-top: 9px; border: 0; padding: 0; color: var(--coral-dark); background: transparent; font-size: 12px; font-weight: 780; }
.inline-editor { grid-column: 2 / 4; padding-top: 17px; border-top: 1px solid var(--line); }
.inline-editor h4 { margin: 0 0 13px; font-size: 14px; }
.tag-editor { position: relative; width: min(370px, 100%); }
.tag-suggestions { margin-top: 6px; overflow: hidden; border: 1px solid var(--line); border-radius: 9px; background: #fff; box-shadow: 0 9px 25px rgba(21,45,42,.09); }
.tag-suggestion { width: 100%; display: flex; justify-content: space-between; gap: 15px; border: 0; padding: 10px 11px; color: var(--ink); background: #fff; text-align: left; }
.tag-suggestion:hover { background: var(--mint); }
.tag-suggestion span:last-child { color: var(--muted); font-size: 11px; }
.read-later-empty-note { margin-top: 9px; color: var(--muted); font-size: 12px; }
.toast { position: fixed; z-index: 20; right: 24px; bottom: 24px; max-width: min(390px, calc(100vw - 48px)); border-radius: 10px; padding: 12px 15px; color: #fff; background: var(--navy-dark); box-shadow: 0 14px 40px rgba(10,28,27,.25); opacity: 0; transform: translateY(8px); pointer-events: none; transition: opacity .2s, transform .2s; font-size: 13px; }
.toast.is-visible { opacity: 1; transform: translateY(0); }

@media (max-width: 900px) {
  .app-shell { grid-template-columns: 220px minmax(0,1fr); }
  .main { padding: 40px 32px 70px; }
  .save-copy { display: block; }
  .save-copy p { margin-top: 5px; }
  .bookmark-card { grid-template-columns: 46px minmax(0,1fr); }
  .card-actions { grid-column: 2; justify-content: flex-start; }
  .inline-editor { grid-column: 1 / 3; }
}

@media (max-width: 680px) {
  .app-shell { display: block; }
  .sidebar { position: static; width: 100%; height: auto; padding: 20px; }
  .primary-nav { margin-top: 22px; display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
  .primary-nav .nav-heading { grid-column: 1 / 3; }
  .tag-nav { margin-top: 20px; }
  #sidebar-tags { display: flex; flex-wrap: wrap; gap: 6px; }
  .tag-nav-button { width: auto; grid-template-columns: 10px 1fr auto; background: rgba(255,255,255,.06); }
  .main { padding: 30px 18px 60px; }
  .save-row { grid-template-columns: 1fr; }
  .save-row .button { width: 100%; }
  .manual-heading { display: block; }
  .domain-badge { display: inline-block; margin-top: 9px; }
  .bookmark-card { padding: 15px; gap: 12px; }
  .site-mark { width: 42px; height: 42px; }
}

